[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en" class="dark">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Leap Studio — Your Reinvention and Experience Partner</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap" rel="stylesheet">
<script src="https://cdn.tailwindcss.com"></script>
<script src="https://unpkg.com/lucide@latest/dist/umd/lucide.min.js"></script>
<script>
  tailwind.config = {
    darkMode: 'class',
    theme: {
      extend: {
        fontFamily: { sans: ['Inter', 'system-ui', 'sans-serif'] },
        colors: {
          surface: '#141414',
          border: '#262626',
          muted: '#888888',
          accent: '#3B82F6',
          'accent-warm': '#F59E0B'
        }
      }
    }
  }
</script>
<style>
  * { box-sizing: border-box; }
  html { scroll-behavior: smooth; }
  body {
    font-family: 'Inter', system-ui, sans-serif;
    background: #0A0A0A;
    color: #FFFFFF;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    overflow-x: hidden;
  }

  /* Hero Carousel */
  .hero-slide {
    position: absolute;
    inset: 0;
    opacity: 0;
    transition: opacity 0.8s cubic-bezier(0.4, 0, 0.2, 1);
    pointer-events: none;
  }
  .hero-slide.active {
    opacity: 1;
    pointer-events: auto;
  }
  .hero-dot {
    width: 10px; height: 10px;
    border-radius: 50%;
    background: rgba(255,255,255,0.3);
    transition: all 0.3s ease;
    cursor: pointer;
  }
  .hero-dot.active { background: #3B82F6; width: 32px; border-radius: 5px; }

  /* Region Tabs */
  .region-tab {
    padding: 0.625rem 1.5rem;
    border-radius: 9999px;
    font-size: 0.875rem;
    font-weight: 500;
    color: #888888;
    cursor: pointer;
    transition: all 0.2s ease;
    border: 1px solid #262626;
    background: transparent;
    white-space: nowrap;
  }
  .region-tab:hover { color: #fff; border-color: #444; }
  .region-tab.active { background: #3B82F6; color: #fff; border-color: #3B82F6; }

  /* Team Cards */
  .team-card {
    display: none;
    animation: fadeSlideUp 0.5s ease-out;
  }
  .team-card.visible { display: flex; }

  /* Work horizontal scroll */
  .work-scroll {
    overflow-x: auto;
    scroll-snap-type: x mandatory;
    -webkit-overflow-scrolling: touch;
    scrollbar-width: none;
    -ms-overflow-style: none;
  }
  .work-scroll::-webkit-scrollbar { display: none; }
  .work-card {
    scroll-snap-align: start;
    flex-shrink: 0;
  }

  /* Language dropdown */
  .lang-dropdown {
    position: absolute;
    top: 100%;
    right: 0;
    margin-top: 0.5rem;
    background: #1A1A1A;
    border: 1px solid #262626;
    border-radius: 0.75rem;
    padding: 0.5rem;
    min-width: 200px;
    opacity: 0;
    visibility: hidden;
    transform: translateY(-8px);
    transition: all 0.2s ease;
    z-index: 100;
  }
  .lang-dropdown.open { opacity: 1; visibility: visible; transform: translateY(0); }
  .lang-option {
    display: flex; align-items: center; gap: 0.5rem;
    padding: 0.625rem 0.75rem;
    border-radius: 0.5rem;
    cursor: pointer;
    transition: background 0.15s ease;
    font-size: 0.875rem;
  }
  .lang-option:hover { background: #262626; }
  .lang-option.active { color: #3B82F6; }

  /* Cookie Banner */
  .cookie-banner {
    position: fixed;
    bottom: 1.5rem;
    left: 50%;
    transform: translateX(-50%) translateY(120px);
    background: #1A1A1A;
    border: 1px solid #262626;
    border-radius: 1rem;
    padding: 1.25rem 1.5rem;
    display: flex;
    align-items: center;
    gap: 1.5rem;
    z-index: 1000;
    max-width: 90vw;
    width: 720px;
    transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1);
    box-shadow: 0 20px 60px rgba(0,0,0,0.5);
  }
  .cookie-banner.visible { transform: translateX(-50%) translateY(0); }
  .cookie-banner.hidden-banner { transform: translateX(-50%) translateY(120px); }

  /* Mobile nav */
  .mobile-menu {
    position: fixed;
    inset: 0;
    background: #0A0A0A;
    z-index: 200;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    gap: 2rem;
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.3s ease;
  }
  .mobile-menu.open { opacity: 1; pointer-events: auto; }

  /* Animations */
  @keyframes fadeSlideUp {
    from { opacity: 0; transform: translateY(20px); }
    to { opacity: 1; transform: translateY(0); }
  }
  .animate-fade-up {
    animation: fadeSlideUp 0.6s ease-out both;
  }
  .delay-100 { animation-delay: 0.1s; }
  .delay-200 { animation-delay: 0.2s; }
  .delay-300 { animation-delay: 0.3s; }
  .delay-400 { animation-delay: 0.4s; }

  /* Scroll animations */
  .reveal {
    opacity: 0;
    transform: translateY(30px);
    transition: opacity 0.7s ease-out, transform 0.7s ease-out;
  }
  .reveal.visible { opacity: 1; transform: translateY(0); }

  @media (max-width: 768px) {
    .cookie-banner {
      flex-direction: column;
      text-align: center;
      padding: 1rem;
      gap: 1rem;
      width: calc(100vw - 2rem);
      bottom: 1rem;
    }
  }
</style>
</head>
<body>

<!-- ─────────────────── NAVIGATION ─────────────────── -->
<nav class="fixed top-0 inset-x-0 z-50 bg-[#0A0A0A]/80 backdrop-blur-xl border-b border-[#1A1A1A]">
  <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
    <div class="flex items-center justify-between h-16">
      <!-- Logo -->
      <a href="#" class="flex items-center gap-2 shrink-0">
        <div class="w-8 h-8 rounded-lg bg-white flex items-center justify-center">
          <span class="text-black font-extrabold text-sm tracking-tight">L</span>
        </div>
        <span class="text-white font-bold text-lg tracking-tight hidden sm:block">Leap Studio</span>
      </a>

      <!-- Desktop nav links -->
      <div class="hidden lg:flex items-center gap-1">
        <a href="#insights" class="px-3 py-2 text-sm text-[#888] hover:text-white transition-colors rounded-lg hover:bg-[#1A1A1A]">Insights</a>
        <a href="#work" class="px-3 py-2 text-sm text-[#888] hover:text-white transition-colors rounded-lg hover:bg-[#1A1A1A]">Work</a>
        <a href="#how-we-work" class="px-3 py-2 text-sm text-[#888] hover:text-white transition-colors rounded-lg hover:bg-[#1A1A1A]">Services</a>
        <a href="#principles" class="px-3 py-2 text-sm text-[#888] hover:text-white transition-colors rounded-lg hover:bg-[#1A1A1A]">Culture</a>
        <a href="#footer" class="px-3 py-2 text-sm text-[#888] hover:text-white transition-colors rounded-lg hover:bg-[#1A1A1A]">Make Your Mark</a>
        <a href="#cta" class="px-3 py-2 text-sm text-white bg-[#1A1A1A] hover:bg-[#262626] transition-colors rounded-lg">Contact Us</a>
      </div>

      <!-- Right: Language + Mobile toggle -->
      <div class="flex items-center gap-3">
        <div class="relative">
          <button id="langBtn" class="flex items-center gap-1.5 px-2.5 py-1.5 text-sm text-[#888] hover:text-white transition-colors rounded-lg hover:bg-[#1A1A1A]">
            <i data-lucide="globe" class="w-4 h-4"></i>
            <span id="currentLang">Global EN</span>
            <i data-lucide="chevron-down" class="w-3.5 h-3.5"></i>
          </button>
          <div id="langDropdown" class="lang-dropdown">
            <div class="lang-option active" data-lang="en" data-label="Global EN">🌐 Global EN</div>
            <div class="lang-option" data-lang="fr" data-label="France FR">🇫🇷 France FR</div>
            <div class="lang-option" data-lang="zh" data-label="China CN">🇨🇳 China CN</div>
          </div>
        </div>
        <button id="mobileMenuBtn" class="lg:hidden p-2 text-[#888] hover:text-white transition-colors">
          <i data-lucide="menu" class="w-5 h-5"></i>
        </button>
      </div>
    </div>
  </div>
</nav>

<!-- Mobile Menu -->
<div id="mobileMenu" class="mobile-menu">
  <button id="mobileCloseBtn" class="absolute top-5 right-5 p-2 text-[#888] hover:text-white">
    <i data-lucide="x" class="w-6 h-6"></i>
  </button>
  <a href="#insights" class="text-2xl font-semibold text-white hover:text-accent transition-colors mobile-nav-link">Insights</a>
  <a href="#work" class="text-2xl font-semibold text-white hover:text-accent transition-colors mobile-nav-link">Work</a>
  <a href="#how-we-work" class="text-2xl font-semibold text-white hover:text-accent transition-colors mobile-nav-link">Services</a>
  <a href="#principles" class="text-2xl font-semibold text-white hover:text-accent transition-colors mobile-nav-link">Culture</a>
  <a href="#footer" class="text-2xl font-semibold text-white hover:text-accent transition-colors mobile-nav-link">Make Your Mark</a>
  <a href="#cta" class="text-2xl font-semibold text-accent hover:text-white transition-colors mobile-nav-link">Contact Us</a>
</div>


<!-- ═══════════════════ HERO CAROUSEL ═══════════════════ -->
<section id="hero" class="relative min-h-screen flex items-center overflow-hidden pt-16">
  <!-- Background gradient -->
  <div class="absolute inset-0 bg-gradient-to-br from-[#0A0A0A] via-[#0D1117] to-[#0A0A0A]"></div>
  <div class="absolute top-1/4 right-0 w-[600px] h-[600px] bg-accent/5 rounded-full blur-[120px]"></div>
  <div class="absolute bottom-1/4 left-0 w-[400px] h-[400px] bg-accent-warm/5 rounded-full blur-[100px]"></div>

  <div class="relative w-full max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-20">
    <div class="relative" style="min-height: 420px;">

      <!-- Slide 1 -->
      <div class="hero-slide active" data-slide="0">
        <div class="grid lg:grid-cols-2 gap-12 items-center">
          <div>
            <div class="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-accent/10 border border-accent/20 text-accent text-xs font-medium mb-6">
              <span class="w-2 h-2 rounded-full bg-accent animate-pulse"></span>
              Insight Report
            </div>
            <h1 class="text-4xl sm:text-5xl lg:text-6xl font-extrabold leading-[1.05] tracking-tight mb-6">
              Futurescape:<br><span class="text-accent">Synthetic Realities</span>
            </h1>
            <p class="text-lg text-[#999] max-w-lg mb-8 leading-relaxed">
              Welcome to the Futurescape. Discover trends and insights on the future of human-AI chemistry — exploring the convergence of synthetic media, generative creativity, and human experience.
            </p>
            <a href="#" class="inline-flex items-center gap-2 px-6 py-3 bg-white text-black font-semibold rounded-full hover:bg-[#e5e5e5] transition-all hover:gap-3">
              Read the report
              <i data-lucide="arrow-right" class="w-4 h-4"></i>
            </a>
          </div>
          <div class="relative">
            <div class="aspect-[4/3] rounded-2xl bg-gradient-to-br from-accent/20 to-accent-warm/10 border border-[#1A1A1A] overflow-hidden flex items-center justify-center">
              <img src="https://images.unsplash.com/photo-1633356122544-f134324a6cee?w=800&h=600&fit=crop" alt="Synthetic Realities" class="w-full h-full object-cover opacity-70">
            </div>
          </div>
        </div>
      </div>

      <!-- Slide 2 -->
      <div class="hero-slide" data-slide="1">
        <div class="grid lg:grid-cols-2 gap-12 items-center">
          <div>
            <div class="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-accent/10 border border-accent/20 text-accent text-xs font-medium mb-6">
              <span class="w-2 h-2 rounded-full bg-accent animate-pulse"></span>
              Featured Work
            </div>
            <h1 class="text-4xl sm:text-5xl lg:text-6xl font-extrabold leading-[1.05] tracking-tight mb-6">
              Designing Robots<br>for <span class="text-accent">Human Spaces</span>
            </h1>
            <p class="text-lg text-[#999] max-w-lg mb-8 leading-relaxed">
              Meet 'Aura,' a concept from Leap Studio that offers a human-centered approach to physical AI — reimagining how autonomous systems integrate into everyday environments.
            </p>
            <a href="#" class="inline-flex items-center gap-2 px-6 py-3 bg-white text-black font-semibold rounded-full hover:bg-[#e5e5e5] transition-all hover:gap-3">
              Explore the work
              <i data-lucide="arrow-right" class="w-4 h-4"></i>
            </a>
          </div>
          <div class="relative">
            <div class="aspect-[4/3] rounded-2xl bg-gradient-to-br from-accent/20 to-accent-warm/10 border border-[#1A1A1A] overflow-hidden flex items-center justify-center">
              <img src="https://images.unsplash.com/photo-1485827404703-89b55fcc595e?w=800&h=600&fit=crop" alt="Robots for Human Spaces" class="w-full h-full object-cover opacity-70">
            </div>
          </div>
        </div>
      </div>

      <!-- Slide 3 -->
      <div class="hero-slide" data-slide="2">
        <div class="grid lg:grid-cols-2 gap-12 items-center">
          <div>
            <div class="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-accent/10 border border-accent/20 text-accent text-xs font-medium mb-6">
              <span class="w-2 h-2 rounded-full bg-accent animate-pulse"></span>
              Article
            </div>
            <h1 class="text-4xl sm:text-5xl lg:text-6xl font-extrabold leading-[1.05] tracking-tight mb-6">
              Amplifying Clinical<br>Care with <span class="text-accent">AI</span>
            </h1>
            <p class="text-lg text-[#999] max-w-lg mb-8 leading-relaxed">
              Examining how service design helps experts understand the healthcare ecosystem — from patient journeys to clinical workflows enhanced by artificial intelligence.
            </p>
            <a href="#" class="inline-flex items-center gap-2 px-6 py-3 bg-white text-black font-semibold rounded-full hover:bg-[#e5e5e5] transition-all hover:gap-3">
              Explore now
              <i data-lucide="arrow-right" class="w-4 h-4"></i>
            </a>
          </div>
          <div class="relative">
            <div class="aspect-[4/3] rounded-2xl bg-gradient-to-br from-accent/20 to-accent-warm/10 border border-[#1A1A1A] overflow-hidden flex items-center justify-center">
              <img src="https://images.unsplash.com/photo-1576091160550-2173dba999ef?w=800&h=600&fit=crop" alt="Clinical Care AI" class="w-full h-full object-cover opacity-70">
            </div>
          </div>
        </div>
      </div>

      <!-- Slide 4 -->
      <div class="hero-slide" data-slide="3">
        <div class="grid lg:grid-cols-2 gap-12 items-center">
          <div>
            <div class="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-accent/10 border border-accent/20 text-accent text-xs font-medium mb-6">
              <span class="w-2 h-2 rounded-full bg-accent animate-pulse"></span>
              Podcast
            </div>
            <h1 class="text-4xl sm:text-5xl lg:text-6xl font-extrabold leading-[1.05] tracking-tight mb-6">
              Design Mind<br><span class="text-accent">Leapcast Ep. 55</span>
            </h1>
            <p class="text-lg text-[#999] max-w-lg mb-8 leading-relaxed">
              Peter Hallström, Global Head of Design at Lumina Health, discusses the evolution of product design and the role of design leadership in shaping tomorrow's experiences.
            </p>
            <a href="#" class="inline-flex items-center gap-2 px-6 py-3 bg-white text-black font-semibold rounded-full hover:bg-[#e5e5e5] transition-all hover:gap-3">
              Listen now
              <i data-lucide="headphones" class="w-4 h-4"></i>
            </a>
          </div>
          <div class="relative">
            <div class="aspect-[4/3] rounded-2xl bg-gradient-to-br from-accent/20 to-accent-warm/10 border border-[#1A1A1A] overflow-hidden flex items-center justify-center">
              <img src="https://images.unsplash.com/photo-1590602847861-f357a9332bbc?w=800&h=600&fit=crop" alt="Design Mind Podcast" class="w-full h-full object-cover opacity-70">
            </div>
          </div>
        </div>
      </div>

      <!-- Slide 5 -->
      <div class="hero-slide" data-slide="4">
        <div class="grid lg:grid-cols-2 gap-12 items-center">
          <div>
            <div class="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-accent/10 border border-accent/20 text-accent text-xs font-medium mb-6">
              <span class="w-2 h-2 rounded-full bg-accent animate-pulse"></span>
              Insight Report
            </div>
            <h1 class="text-4xl sm:text-5xl lg:text-6xl font-extrabold leading-[1.05] tracking-tight mb-6">
              From Complexity<br>to <span class="text-accent">Clarity</span>
            </h1>
            <p class="text-lg text-[#999] max-w-lg mb-8 leading-relaxed">
              Dive into new research on how CMOs can reclaim marketing to build competitive edge — transforming fragmented data into unified, actionable intelligence.
            </p>
            <a href="#" class="inline-flex items-center gap-2 px-6 py-3 bg-white text-black font-semibold rounded-full hover:bg-[#e5e5e5] transition-all hover:gap-3">
              Read the report
              <i data-lucide="arrow-right" class="w-4 h-4"></i>
            </a>
          </div>
          <div class="relative">
            <div class="aspect-[4/3] rounded-2xl bg-gradient-to-br from-accent/20 to-accent-warm/10 border border-[#1A1A1A] overflow-hidden flex items-center justify-center">
              <img src="https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=800&h=600&fit=crop" alt="Complexity to Clarity" class="w-full h-full object-cover opacity-70">
            </div>
          </div>
        </div>
      </div>

    </div>

    <!-- Controls -->
    <div class="flex items-center gap-4 mt-10">
      <button id="heroPrev" class="p-2 rounded-full border border-[#262626] text-[#888] hover:text-white hover:border-[#444] transition-all">
        <i data-lucide="arrow-left" class="w-5 h-5"></i>
      </button>
      <div class="flex items-center gap-2" id="heroDots">
        <span class="hero-dot active" data-index="0"></span>
        <span class="hero-dot" data-index="1"></span>
        <span class="hero-dot" data-index="2"></span>
        <span class="hero-dot" data-index="3"></span>
        <span class="hero-dot" data-index="4"></span>
      </div>
      <button id="heroNext" class="p-2 rounded-full border border-[#262626] text-[#888] hover:text-white hover:border-[#444] transition-all">
        <i data-lucide="arrow-right" class="w-5 h-5"></i>
      </button>
      <span class="text-xs text-[#555] ml-2"><span id="heroCurrent">1</span> / 5</span>
    </div>
  </div>
</section>


<!-- ═══════════════════ TEAM CAROUSEL ═══════════════════ -->
<section id="team" class="py-24 sm:py-32 relative">
  <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
    <div class="text-center mb-14 reveal">
      <h2 class="text-3xl sm:text-4xl lg:text-5xl font-bold tracking-tight mb-4">
        Welcome to <span class="text-accent">the studio</span>
      </h2>
      <p class="text-lg text-[#888] max-w-2xl mx-auto">
        Meet the team making an impact for leading brands around the globe.
      </p>
    </div>

    <!-- Region Tabs -->
    <div class="flex flex-wrap justify-center gap-2 mb-12 reveal">
      <button class="region-tab active" data-region="north-america">North America</button>
      <button class="region-tab" data-region="asia">Asia</button>
      <button class="region-tab" data-region="europe">Europe</button>
      <button class="region-tab" data-region="oceania">Oceania</button>
    </div>

    <!-- Team Cards Container -->
    <div id="teamCards" class="grid sm:grid-cols-2 lg:grid-cols-3 gap-6">
      <!-- North America -->
      <div class="team-card visible flex-col p-6 rounded-2xl bg-[#141414] border border-[#1A1A1A] hover:border-[#2A2A2A] transition-all duration-300" data-region="north-america">
        <div class="w-full aspect-[3/4] rounded-xl overflow-hidden mb-5 bg-[#1A1A1A]">
          <img src="https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?w=400&h=533&fit=crop" alt="Denice Alvarez" class="w-full h-full object-cover" loading="lazy">
        </div>
        <h3 class="text-lg font-semibold">Denice Alvarez</h3>
        <p class="text-sm text-accent mb-3">Office Manager</p>
        <p class="text-sm text-[#666] leading-relaxed mb-2 flex-1">"As the Office Manager, I engage with teams from every discipline, and have learned so much through my day-to-day interactions with my fellow leapers."</p>
        <div class="flex items-center justify-between mt-4 pt-4 border-t border-[#1A1A1A]">
          <span class="text-xs text-[#555]">New York</span>
          <a href="#" class="text-xs text-accent hover:text-white transition-colors">Contact Leap Studio New York →</a>
        </div>
      </div>

      <div class="team-card visible flex-col p-6 rounded-2xl bg-[#141414] border border-[#1A1A1A] hover:border-[#2A2A2A] transition-all duration-300" data-region="north-america">
        <div class="w-full aspect-[3/4] rounded-xl overflow-hidden mb-5 bg-[#1A1A1A]">
          <img src="https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=400&h=533&fit=crop" alt="Marco Bellini" class="w-full h-full object-cover" loading="lazy">
        </div>
        <h3 class="text-lg font-semibold">Marco Bellini</h3>
        <p class="text-sm text-accent mb-3">Design Director</p>
        <p class="text-sm text-[#666] leading-relaxed mb-2 flex-1">"Every day we are delighted by the immense beauty that nature holds. When engaged in the act of creation, it is our responsibility to channel that delight into the things we make."</p>
        <div class="flex items-center justify-between mt-4 pt-4 border-t border-[#1A1A1A]">
          <span class="text-xs text-[#555]">San Francisco</span>
          <a href="#" class="text-xs text-accent hover:text-white transition-colors">Contact Leap Studio San Francisco →</a>
        </div>
      </div>

      <!-- Asia -->
