<script>
// ─── Initialize Lucide Icons ───
lucide.createIcons();

// ─── HERO CAROUSEL ───
(function() {
  const slides = document.querySelectorAll('.hero-slide');
  const dots = document.querySelectorAll('.hero-dot');
  const prevBtn = document.getElementById('heroPrev');
  const nextBtn = document.getElementById('heroNext');
  const currentEl = document.getElementById('heroCurrent');
  let currentSlide = 0;
  let autoplayInterval;
  const totalSlides = slides.length;

  function goToSlide(index) {
    slides[currentSlide].classList.remove('active');
    dots[currentSlide].classList.remove('active');
    currentSlide = (index + totalSlides) % totalSlides;
    slides[currentSlide].classList.add('active');
    dots[currentSlide].classList.add('active');
    currentEl.textContent = currentSlide + 1;
  }

  function nextSlide() { goToSlide(currentSlide + 1); }
  function prevSlide() { goToSlide(currentSlide - 1); }

  nextBtn.addEventListener('click', () => { nextSlide(); resetAutoplay(); });
  prevBtn.addEventListener('click', () => { prevSlide(); resetAutoplay(); });
  dots.forEach(dot => {
    dot.addEventListener('click', () => { goToSlide(parseInt(dot.dataset.index)); resetAutoplay(); });
  });

  function startAutoplay() {
    autoplayInterval = setInterval(nextSlide, 6000);
  }
  function resetAutoplay() {
    clearInterval(autoplayInterval);
    startAutoplay();
  }
  startAutoplay();

  // Touch/swipe support for hero
  let touchStartX = 0;
  const heroSection = document.getElementById('hero');
  heroSection.addEventListener('touchstart', (e) => { touchStartX = e.touches[0].clientX; });
  heroSection.addEventListener('touchend', (e) => {
    const diff = touchStartX - e.changedTouches[0].clientX;
    if (Math.abs(diff) > 50) {
      diff > 0 ? nextSlide() : prevSlide();
      resetAutoplay();
    }
  });
})();

// ─── TEAM REGION TOGGLE ───
(function() {
  const regionTabs = document.querySelectorAll('.region-tab');
  const teamCards = document.querySelectorAll('.team-card');
  const teamCounter = document.getElementById('teamCounter');

  function filterTeam(region) {
    let visibleCount = 0;
    teamCards.forEach(card => {
      if (card.dataset.region === region) {
        card.classList.add('visible');
        visibleCount++;
      } else {
        card.classList.remove('visible');
      }
    });
    teamCounter.textContent = visibleCount + ' team member' + (visibleCount !== 1 ? 's' : '');
  }

  regionTabs.forEach(tab => {
    tab.addEventListener('click', () => {
      regionTabs.forEach(t => t.classList.remove('active'));
      tab.classList.add('active');
      filterTeam(tab.dataset.region);
    });
  });
})();

// ─── WORK HORIZONTAL SCROLL ───
(function() {
  const scrollContainer = document.getElementById('workScroll');
  const leftBtn = document.getElementById('workScrollLeft');
  const rightBtn = document.getElementById('workScrollRight');
  const scrollAmount = 420;

  leftBtn.addEventListener('click', () => {
    scrollContainer.scrollBy({ left: -scrollAmount, behavior: 'smooth' });
  });
  rightBtn.addEventListener('click', () => {
    scrollContainer.scrollBy({ left: scrollAmount, behavior: 'smooth' });
  });
})();

// ─── LANGUAGE DROPDOWN ───
(function() {
  const langBtn = document.getElementById('langBtn');
  const dropdown = document.getElementById('langDropdown');
  const currentLang = document.getElementById('currentLang');
  const options = document.querySelectorAll('.lang-option');

  langBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    dropdown.classList.toggle('open');
  });

  options.forEach(opt => {
    opt.addEventListener('click', () => {
      options.forEach(o => o.classList.remove('active'));
      opt.classList.add('active');
      currentLang.textContent = opt.dataset.label;
      dropdown.classList.remove('open');
    });
  });

  document.addEventListener('click', (e) => {
    if (!langBtn.contains(e.target) && !dropdown.contains(e.target)) {
      dropdown.classList.remove('open');
    }
  });
})();

// ─── COOKIE CONSENT ───
(function() {
  const banner = document.getElementById('cookieBanner');
  const acceptBtn = document.getElementById('cookieAccept');
  const declineBtn = document.getElementById('cookieDecline');
  const settingsBtn = document.getElementById('cookieSettings');

  function hideBanner() {
    banner.classList.remove('visible');
    banner.classList.add('hidden-banner');
    setTimeout(() => { banner.style.display = 'none'; }, 400);
  }

  acceptBtn.addEventListener('click', hideBanner);
  declineBtn.addEventListener('click', hideBanner);
  settingsBtn.addEventListener('click', hideBanner);
})();

// ─── MOBILE MENU ───
(function() {
  const menuBtn = document.getElementById('mobileMenuBtn');
  const closeBtn = document.getElementById('mobileCloseBtn');
  const menu = document.getElementById('mobileMenu');
  const links = document.querySelectorAll('.mobile-nav-link');

  menuBtn.addEventListener('click', () => menu.classList.add('open'));
  closeBtn.addEventListener('click', () => menu.classList.remove('open'));
  links.forEach(link => link.addEventListener('click', () => menu.classList.remove('open')));
})();

// ─── SCROLL REVEAL ANIMATIONS ───
(function() {
  const reveals = document.querySelectorAll('.reveal');
  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('visible');
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: 0.15, rootMargin: '0px 0px -50px 0px' });

  reveals.forEach(el => observer.observe(el));
})();

// ─── SMOOTH SCROLL FOR NAV LINKS ───
document.querySelectorAll('a[href^="#"]').forEach(anchor => {
  anchor.addEventListener('click', function(e) {
    const target = document.querySelector(this.getAttribute('href'));
    if (target) {
      e.preventDefault();
      target.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  });
});
</script>

</body>
</html>
